import React from 'react';
import './Hero.css';

function Hero() {
  const scrollToDetails = () => {
    const element = document.getElementById('details');
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <section id="home" className="hero">
      <div className="hero-content">
        <p className="hero-tagline">Navigating EDventure</p>
        <h1>CRESCENT ACADEMIA<br /><span className="moot-highlight">MOOT 2.0</span></h1>
        <div className="event-dates">
          <p><strong>February 13 - 15, 2026</strong></p>
          <p>at Crescent Model Higher Secondary School (Girls Campus)</p>
        </div>
        <button className="cta-button" onClick={scrollToDetails}>Learn More</button>
      </div>
    </section>
  );
}

export default Hero;
